<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useI18n } from '@/locales'
import { useToast } from 'vue-toastification'
import api from '@/api/client'

const { t, locale } = useI18n(); const toast = useToast(); const loading = ref(false); const cycles = ref([]); const employees = ref([]); const selected = ref(null); const showCreate = ref(false); const letter = ref(null)
const cycleForm = reactive({ code: '', name: '', effective_date: '', approval_levels: 2 }); const budgetAmount = ref(0); const proposal = reactive({ employee_id: '', proposed_salary: '', performance_score: '', calibration_input: '' })
const money = value => new Intl.NumberFormat(locale.value === 'id' ? 'id-ID' : 'en-US', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(Number(value || 0))
const increase = row => Number(row.proposed_salary) - Number(row.current_salary)
const canApprove = row => ['SUBMITTED', 'IN_APPROVAL'].includes(row.status)
const summary = computed(() => selected.value?.summary || {})
async function load() { loading.value = true; try { const [cycleResponse, employeeResponse] = await Promise.all([api.get('/compensation-reviews'), api.get('/employees', { params: { per_page: 100, is_active: 1 } })]); cycles.value = cycleResponse.data.data; employees.value = employeeResponse.data.data || []; if (selected.value) await selectCycle(selected.value.id) } catch (e) { toast.error(e.response?.data?.message || t('compensation_review.load_failed')) } finally { loading.value = false } }
async function selectCycle(id) { try { selected.value = (await api.get(`/compensation-reviews/${id}`)).data.data; budgetAmount.value = Number(selected.value.budgets?.[0]?.budget_amount || 0) } catch (e) { toast.error(e.response?.data?.message || t('compensation_review.load_failed')) } }
async function createCycle() { try { const row = (await api.post('/compensation-reviews', cycleForm)).data.data; showCreate.value = false; Object.assign(cycleForm, { code: '', name: '', effective_date: '', approval_levels: 2 }); toast.success(t('compensation_review.created')); await load(); await selectCycle(row.id) } catch (e) { toast.error(e.response?.data?.message || t('compensation_review.action_failed')) } }
async function saveBudget() { try { await api.put(`/compensation-reviews/${selected.value.id}/budgets`, { budgets: [{ budget_amount: Number(budgetAmount.value) }] }); toast.success(t('compensation_review.saved')); await selectCycle(selected.value.id) } catch (e) { toast.error(e.response?.data?.message || t('compensation_review.action_failed')) } }
async function openCycle() { try { await api.post(`/compensation-reviews/${selected.value.id}/open`); toast.success(t('compensation_review.opened')); await load() } catch (e) { toast.error(e.response?.data?.message || t('compensation_review.action_failed')) } }
async function submitProposal() { try { await api.post(`/compensation-reviews/${selected.value.id}/proposals`, { employee_id: Number(proposal.employee_id), proposed_salary: Number(proposal.proposed_salary), performance_score: proposal.performance_score === '' ? null : Number(proposal.performance_score), calibration_input: proposal.calibration_input }); Object.assign(proposal, { employee_id: '', proposed_salary: '', performance_score: '', calibration_input: '' }); toast.success(t('compensation_review.submitted')); await selectCycle(selected.value.id) } catch (e) { toast.error(e.response?.data?.message || t('compensation_review.action_failed')) } }
async function approve(row) { try { await api.post(`/compensation-proposals/${row.id}/approve`); toast.success(t('compensation_review.approved')); await selectCycle(selected.value.id) } catch (e) { toast.error(e.response?.data?.message || t('compensation_review.action_failed')) } }
async function reject(row) { const reason = window.prompt(t('compensation_review.rejection_reason')); if (!reason) return; try { await api.post(`/compensation-proposals/${row.id}/reject`, { reason }); toast.success(t('compensation_review.rejected')); await selectCycle(selected.value.id) } catch (e) { toast.error(e.response?.data?.message || t('compensation_review.action_failed')) } }
async function showLetter(row) { try { letter.value = (await api.get(`/compensation-proposals/${row.id}/letter`)).data.data } catch (e) { toast.error(e.response?.data?.message || t('compensation_review.action_failed')) } }
onMounted(load)
</script>

<template>
  <div class="space-y-5">
    <header class="flex flex-wrap items-start justify-between gap-3"><div><h1 class="text-2xl font-bold">{{ t('compensation_review.title') }}</h1><p class="text-sm text-gray-500">{{ t('compensation_review.subtitle') }}</p></div><div class="flex gap-2"><button class="btn-secondary" @click="load">{{ t('compensation_review.refresh') }}</button><button class="btn-primary" @click="showCreate = !showCreate">{{ t('compensation_review.new_cycle') }}</button></div></header>
    <form v-if="showCreate" class="card-body grid gap-3 md:grid-cols-5" @submit.prevent="createCycle"><label class="text-xs text-gray-500">{{ t('compensation_review.code') }}<input v-model="cycleForm.code" class="form-input mt-1 w-full" required></label><label class="text-xs text-gray-500">{{ t('compensation_review.name') }}<input v-model="cycleForm.name" class="form-input mt-1 w-full" required></label><label class="text-xs text-gray-500">{{ t('compensation_review.effective_date') }}<input v-model="cycleForm.effective_date" class="form-input mt-1 w-full" required type="date"></label><label class="text-xs text-gray-500">{{ t('compensation_review.approval_levels') }}<input v-model.number="cycleForm.approval_levels" class="form-input mt-1 w-full" min="1" max="5" type="number"></label><button class="btn-primary self-end">{{ t('compensation_review.create') }}</button></form>
    <div class="grid gap-4 lg:grid-cols-[280px_1fr]">
      <aside class="card overflow-hidden"><div class="border-b p-3 font-semibold">{{ t('compensation_review.cycles') }}</div><div v-if="loading" class="p-4 text-sm text-gray-500">{{ t('compensation_review.loading') }}</div><button v-for="cycle in cycles" :key="cycle.id" class="block w-full border-b p-3 text-left hover:bg-gray-50" :class="selected?.id === cycle.id ? 'bg-blue-50' : ''" @click="selectCycle(cycle.id)"><div class="font-medium">{{ cycle.name }}</div><div class="mt-1 flex justify-between text-xs text-gray-500"><span>{{ cycle.effective_date }}</span><span>{{ cycle.status }}</span></div></button><div v-if="!loading && !cycles.length" class="p-4 text-sm text-gray-500">{{ t('compensation_review.no_cycles') }}</div></aside>
      <main v-if="selected" class="space-y-4">
        <div class="grid gap-3 sm:grid-cols-3"><div class="card-body"><div class="text-xs text-gray-500">{{ t('compensation_review.budget') }}</div><b>{{ money(summary.budget) }}</b></div><div class="card-body"><div class="text-xs text-gray-500">{{ t('compensation_review.used') }}</div><b>{{ money(summary.approved_increase) }}</b></div><div class="card-body"><div class="text-xs text-gray-500">{{ t('compensation_review.remaining') }}</div><b>{{ money(summary.remaining) }}</b></div></div>
        <section v-if="selected.status === 'DRAFT'" class="card-body flex flex-wrap items-end gap-3"><label class="flex-1 text-sm">{{ t('compensation_review.global_budget') }}<input v-model.number="budgetAmount" class="form-input mt-1 w-full" min="0" type="number"></label><button class="btn-secondary" @click="saveBudget">{{ t('compensation_review.save_budget') }}</button><button class="btn-primary" @click="openCycle">{{ t('compensation_review.open_cycle') }}</button></section>
        <form v-if="selected.status === 'OPEN'" class="card-body grid gap-3 md:grid-cols-5" @submit.prevent="submitProposal"><label class="text-xs text-gray-500">{{ t('compensation_review.employee') }}<select v-model="proposal.employee_id" required class="form-input mt-1 w-full"><option value="" disabled>—</option><option v-for="employee in employees" :key="employee.id" :value="employee.id">{{ employee.employee_number }} · {{ employee.full_name }}</option></select></label><label class="text-xs text-gray-500">{{ t('compensation_review.proposed_salary') }}<input v-model="proposal.proposed_salary" required type="number" class="form-input mt-1 w-full"></label><label class="text-xs text-gray-500">{{ t('compensation_review.performance_score') }}<input v-model="proposal.performance_score" type="number" min="0" max="5" step="0.01" class="form-input mt-1 w-full"></label><label class="text-xs text-gray-500">{{ t('compensation_review.calibration') }}<input v-model="proposal.calibration_input" class="form-input mt-1 w-full"></label><button class="btn-primary self-end">{{ t('compensation_review.submit_proposal') }}</button></form>
        <div class="card overflow-x-auto"><table class="min-w-full text-sm"><thead class="bg-gray-50"><tr><th class="p-3 text-left">{{ t('compensation_review.employee') }}</th><th class="p-3 text-right">{{ t('compensation_review.current_salary') }}</th><th class="p-3 text-right">{{ t('compensation_review.proposed_salary') }}</th><th class="p-3 text-right">{{ t('compensation_review.increase') }}</th><th class="p-3">{{ t('compensation_review.compa_ratio') }}</th><th class="p-3">{{ t('compensation_review.status') }}</th><th class="p-3">{{ t('compensation_review.actions') }}</th></tr></thead><tbody><tr v-for="row in selected.proposals" :key="row.id" class="border-t"><td class="p-3">{{ row.full_name }}<div class="text-xs text-gray-500">{{ row.employee_number }}</div></td><td class="p-3 text-right">{{ money(row.current_salary) }}</td><td class="p-3 text-right">{{ money(row.proposed_salary) }}</td><td class="p-3 text-right">{{ money(increase(row)) }}</td><td class="p-3 text-center">{{ row.compa_ratio ?? '—' }}</td><td class="p-3 text-center">{{ row.status }} ({{ row.approval_level }}/{{ selected.approval_levels }})</td><td class="p-3"><div class="flex justify-center gap-1"><button v-if="canApprove(row)" class="btn-secondary" @click="approve(row)">{{ t('compensation_review.approve') }}</button><button v-if="canApprove(row)" class="btn-secondary" @click="reject(row)">{{ t('compensation_review.reject') }}</button><button v-if="row.status === 'APPROVED'" class="btn-secondary" @click="showLetter(row)">{{ t('compensation_review.letter') }}</button></div></td></tr></tbody></table></div>
      </main>
    </div>
    <div v-if="letter" class="fixed inset-0 z-50 grid place-items-center bg-black/40 p-4"><article class="w-full max-w-lg rounded-lg bg-white p-6"><h2 class="text-xl font-bold">{{ t('compensation_review.letter_title') }}</h2><p class="mt-1 text-sm text-gray-500">{{ t('compensation_review.letter_reference') }}: {{ letter.reference }}</p><div class="mt-5 space-y-2"><p><b>{{ letter.employee.name }}</b> ({{ letter.employee.number }})</p><p>{{ t('compensation_review.current_salary') }}: {{ money(letter.current_salary) }}</p><p>{{ t('compensation_review.new_salary') }}: {{ money(letter.new_salary) }}</p><p>{{ t('compensation_review.effective_date') }}: {{ letter.effective_date }}</p></div><button class="btn-primary mt-5" @click="letter = null">{{ t('compensation_review.close') }}</button></article></div>
  </div>
</template>
